// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccounts List the user's accounts (pockets and categories)
	// (GET /accounts)
	ListAccounts(ctx context.Context, request ListAccountsRequestObject) (ListAccountsResponseObject, error)
	// CreateAccount Create a pocket or category (chart-of-accounts entry)
	// (POST /accounts)
	CreateAccount(ctx context.Context, request CreateAccountRequestObject) (CreateAccountResponseObject, error)
	// GetAccountBalance Account debit/credit totals and normal-balance-signed amount
	// (GET /accounts/{id}/balance)
	GetAccountBalance(ctx context.Context, request GetAccountBalanceRequestObject) (GetAccountBalanceResponseObject, error)
	// GoogleAuth Exchange a Google authorization code for a session
	// (POST /auth/google)
	GoogleAuth(ctx context.Context, request GoogleAuthRequestObject) (GoogleAuthResponseObject, error)
	// Login Exchange credentials for a session
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the presented refresh token
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe Current authenticated user
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Refresh Rotate a refresh token into a new session
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Register Create a credential account and start a session
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ListBudgets List a month's budgets with live spent totals
	// (GET /budgets)
	ListBudgets(ctx context.Context, request ListBudgetsRequestObject) (ListBudgetsResponseObject, error)
	// SetBudget Create or update a monthly category budget
	// (POST /budgets)
	SetBudget(ctx context.Context, request SetBudgetRequestObject) (SetBudgetResponseObject, error)
	// DeleteBudget Delete a budget (idempotent)
	// (DELETE /budgets/{id})
	DeleteBudget(ctx context.Context, request DeleteBudgetRequestObject) (DeleteBudgetResponseObject, error)
	// UpdateBudget Update a budget's target
	// (PUT /budgets/{id})
	UpdateBudget(ctx context.Context, request UpdateBudgetRequestObject) (UpdateBudgetResponseObject, error)
	// ListEntries List posted entries with their lines
	// (GET /entries)
	ListEntries(ctx context.Context, request ListEntriesRequestObject) (ListEntriesResponseObject, error)
	// PostEntry Post a balanced double-entry transaction
	// (POST /entries)
	PostEntry(ctx context.Context, request PostEntryRequestObject) (PostEntryResponseObject, error)
	// GetEntry Fetch one posted entry with its lines
	// (GET /entries/{id})
	GetEntry(ctx context.Context, request GetEntryRequestObject) (GetEntryResponseObject, error)
	// ListFxRates List available FX rates
	// (GET /fx/rates)
	ListFxRates(ctx context.Context, request ListFxRatesRequestObject) (ListFxRatesResponseObject, error)
	// RefreshFxRates Trigger a manual FX rate refresh from frankfurter.app
	// (POST /fx/rates/refresh)
	RefreshFxRates(ctx context.Context, request RefreshFxRatesRequestObject) (RefreshFxRatesResponseObject, error)
	// GetFxRate Get the most recent rate for a currency pair
	// (GET /fx/rates/{base}/{quote})
	GetFxRate(ctx context.Context, request GetFxRateRequestObject) (GetFxRateResponseObject, error)
	// GetHealthz Liveness + DB connectivity
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// ListRecurring List the user's recurring transaction rules
	// (GET /recurring)
	ListRecurring(ctx context.Context, request ListRecurringRequestObject) (ListRecurringResponseObject, error)
	// CreateRecurring Create a recurring transaction rule
	// (POST /recurring)
	CreateRecurring(ctx context.Context, request CreateRecurringRequestObject) (CreateRecurringResponseObject, error)
	// TriggerRecurring Manually trigger materialization of due recurring rules
	// (POST /recurring/trigger)
	TriggerRecurring(ctx context.Context, request TriggerRecurringRequestObject) (TriggerRecurringResponseObject, error)
	// DeleteRecurring Delete a recurring rule (idempotent)
	// (DELETE /recurring/{id})
	DeleteRecurring(ctx context.Context, request DeleteRecurringRequestObject) (DeleteRecurringResponseObject, error)
	// GetRecurring Get one recurring rule
	// (GET /recurring/{id})
	GetRecurring(ctx context.Context, request GetRecurringRequestObject) (GetRecurringResponseObject, error)
	// UpdateRecurring Update a recurring rule
	// (PUT /recurring/{id})
	UpdateRecurring(ctx context.Context, request UpdateRecurringRequestObject) (UpdateRecurringResponseObject, error)
	// GetCashFlow Income vs expense for a period, in base currency
	// (GET /reports/cash-flow)
	GetCashFlow(ctx context.Context, request GetCashFlowRequestObject) (GetCashFlowResponseObject, error)
	// GetMonthlySeries Income / expense / net per month for the trailing N months
	// (GET /reports/monthly)
	GetMonthlySeries(ctx context.Context, request GetMonthlySeriesRequestObject) (GetMonthlySeriesResponseObject, error)
	// GetNetWorth Net worth (assets minus liabilities) in base currency
	// (GET /reports/net-worth)
	GetNetWorth(ctx context.Context, request GetNetWorthRequestObject) (GetNetWorthResponseObject, error)
	// GetSpending Spending by category for a period
	// (GET /reports/spending)
	GetSpending(ctx context.Context, request GetSpendingRequestObject) (GetSpendingResponseObject, error)
	// SyncPull Pull changes since a watermark (WatermelonDB)
	// (GET /sync/pull)
	SyncPull(ctx context.Context, request SyncPullRequestObject) (SyncPullResponseObject, error)
	// SyncPush Push local changes to the server (WatermelonDB)
	// (POST /sync/push)
	SyncPush(ctx context.Context, request SyncPushRequestObject) (SyncPushResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

